"""Prepare the original-host release in an isolated Works authoring workspace.

Fetches one pinned CCN commit, preserves report binaries and other businesses,
repairs existing shared styles/fixtures, and applies files only after the full
Works validation succeeds. Run through Irigit repo.author/exec with an exact
workspace revision and snapshot_message; this script never publishes itself.
Requires the validation environment to have authorized TableGit read access.
"""
import urllib.request,zipfile,tempfile,pathlib,re,json
original=pathlib.Path.cwd();import shutil,subprocess,sys
root=pathlib.Path(tempfile.mkdtemp(prefix='ccn-release-check-'));shutil.copytree(original,root,dirs_exist_ok=True,ignore=shutil.ignore_patterns('.git'))
sha='7932dc1071ae4ff4fc297c23e09eff8e658670b3'
with tempfile.TemporaryDirectory() as td:
 archive=pathlib.Path(td)/'source.zip'
 urllib.request.urlretrieve('https://codeload.github.com/c1917797-bit/CCN-insight/zip/'+sha,archive)
 z=zipfile.ZipFile(archive);prefix='CCN-insight-'+sha+'/dist/business_insight/cloud_core/'
 copied=0;html_pages=[]
 for name in z.namelist():
  if not name.startswith(prefix) or name.endswith('/'):continue
  rel=name[len(prefix):];p=pathlib.PurePosixPath(rel)
  if p.is_absolute() or '..' in p.parts:raise RuntimeError('unsafe path')
  if p.parts[0]=='reports' or p.suffix.lower() not in ('.html','.js','.css','.json','.svg','.md'):continue
  data=z.read(name);data.decode('utf-8')
  target=root/'business_insight/cloud_core'/rel;target.parent.mkdir(parents=True,exist_ok=True);target.write_bytes(data);copied+=1
  if target.suffix=='.html':html_pages.append(target)
 folder=root/'business_insight/cloud_core';css=root/'assets/insight-executive.css';extra=[]
 for page in html_pages:
  if 'reports' in page.relative_to(folder).parts:continue
  s=page.read_text();blocks=re.findall(r'<style[^>]*>([\s\S]*?)</style>',s,flags=re.I)
  if not blocks:continue
  ident=page.relative_to(folder).as_posix().replace('/','-').replace('.','-')
  extra.append('\n'.join(blocks))
  s=re.sub(r'<style[^>]*>[\s\S]*?</style>','',s,flags=re.I)
  s=re.sub(r'<body\b', '<body data-ccn-style="'+ident+'"',s,count=1)
  page.write_text(s)
 css.write_text(css.read_text()+'\n/* CCN imported page styles, isolated per reader page. */\n'+'\n'.join(extra))
